declare @hierarquias table (
griffe varchar(25), 
linha varchar(25), 
grupo_produto varchar(25),
subgrupo_produto  varchar(25)
)


;WITH BASE (griffe, linha, grupo_produto,subgrupo_produto,UNOUS_NIVEL)
AS (
select a.*, max(b.UNOUS_NIVEL) as UNOUS_NIVEL
from @hierarquias a
left join CAE_PRODUTOS_FATOR_P b 
			on b.griffe = a.griffe and  b.linha = a.linha 
				and b.grupo_produto = a.grupo_produto and b.SUBGRUPO_PRODUTO=a.subgrupo_produto
group by a.griffe, a.linha, a.grupo_produto, a.subgrupo_produto)

SELECT a.*, p.PRODUTO, p.DESC_PRODUTO, p.INATIVO, p.DATA_CADASTRAMENTO, pp.VALOR_PROPRIEDADE 
FROM BASE A
INNER JOIN PRODUTOS P 
			ON p.griffe = a.griffe and  p.linha = a.linha 
				and p.grupo_produto = a.grupo_produto and p.SUBGRUPO_PRODUTO=a.subgrupo_produto
INNER JOIN PROP_PRODUTOS pp on pp.PRODUTO = p.PRODUTO and pp.PROPRIEDADE='00105'
where p.INATIVO=0
order by a.griffe, a.linha, a.grupo_produto, a.subgrupo_produto, p.PRODUTO


